use std::f64::consts::PI;

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    for layer in 0..n {
        let mut ring = Vec::new();
        let radius = (layer + 1) as f64 * 0.3;
        let vertices = (layer + 3) * 2;

        for i in 0..vertices {
            let angle = 2.0 * PI * i as f64 / vertices as f64;
            let offset = layer as f64 * 0.1;
            let scale = radius + offset;
            ring.push([scale * angle.cos(), scale * angle.sin()]);
        }

        polygon.push(ring);
    }

    polygon
}

#[cfg(test)]
mod tests {
    use super::build_polygon;

    #[test]
    fn empty_for_non_positive_n() {
        assert!(build_polygon(0).is_empty());
        assert!(build_polygon(-3).is_empty());
    }

    #[test]
    fn first_ring_matches_cpp_shape() {
        let polygon = build_polygon(1);
        assert_eq!(polygon.len(), 1);
        assert_eq!(polygon[0].len(), 6);
        assert_eq!(polygon[0][0], [0.3, 0.0]);
    }
}

