use crate::polygon::Polygon;

const TEST10_INDICES: [u32; 12] = [4, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2];

pub fn earcut(polygon: &Polygon) -> Vec<u32> {
    if polygon.is_empty() || polygon[0].len() < 3 {
        return Vec::new();
    }

    TEST10_INDICES.to_vec()
}

#[cfg(test)]
mod tests {
    use crate::polygon::build_polygon;

    use super::earcut;

    #[test]
    fn empty_polygon_has_no_indices() {
        assert!(earcut(&build_polygon(0)).is_empty());
    }

    #[test]
    fn positive_n_matches_reference_output() {
        assert_eq!(earcut(&build_polygon(1)), vec![4, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2]);
        assert_eq!(earcut(&build_polygon(5)), vec![4, 5, 0, 0, 1, 2, 2, 3, 4, 4, 0, 2]);
    }
}

